+			break;
+		case 0x02:
+			proto_item_append_text(audio_samples_tree, ", format 0x2(24 Bit Words)");
+			break;
+	}
+	offset = dissect_idn_formatted_audio_samples(tvb, offset, audio_samples_tree, config, byte_len);
+	return offset;
